import{_ as i,a0 as p,w as o,s as r,I as s,x as e,a1 as n,A as l,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"在 Ubuntu Mate 16.04 上通過 PPA  升級 Mate 1.14 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu Mate 16.04 上通過 PPA  升級 Mate 1.14 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu Mate 16.04 上通過 PPA  升級 Mate 1.14 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu Mate 16.04 上通過 PPA  升級 Mate 1.14 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160609 INSTALL MATE 1.14 IN UBUNTU MATE 16.04  VIA PPA","title":"在 Ubuntu Mate 16.04 上通過 PPA  升級 Mate 1.14","tag":"201607","desc":""},"relativePath":"201607/20160609 INSTALL MATE 1.14 IN UBUNTU MATE 16.04  VIA PPA.md","filePath":"[post].md"}'),d={name:"201607/20160609 INSTALL MATE 1.14 IN UBUNTU MATE 16.04  VIA PPA.md"};function A(T,t,b,m,M,g){const a=p("Link");return o(),r("div",null,[t[21]||(t[21]=s("h1",{id:"在-ubuntu-mate-16-04-上通過-ppa-升級-mate-1-14",tabindex:"-1"},[e("在 Ubuntu Mate 16.04 上通過 PPA 升級 Mate 1.14 "),s("a",{class:"header-anchor",href:"#在-ubuntu-mate-16-04-上通過-ppa-升級-mate-1-14","aria-label":"Permalink to “在 Ubuntu Mate 16.04 上通過 PPA  升級 Mate 1.14”"},"​")],-1)),s("p",null,[t[1]||(t[1]=e('Mate 桌面環境 1.14 現在可以在 Ubuntu Mate 16.04 ("Xenial Xerus") 上使用了。根據這個',-1)),n(a,{href:"https://ubuntu-mate.org/blog/mate-desktop-114-for-xenial-xerus/"},{default:l(()=>[...t[0]||(t[0]=[e("發佈版本",-1)])]),_:1}),t[2]||(t[2]=e("的描述，為了全面測試 Mate 1.14，所以 Mate 桌面環境 1.14 已經在 PPA 上發佈 2 個月了。因此，你不太可能遇到安裝的問題。",-1))]),t[22]||(t[22]=u('<p><img src="https://2.bp.blogspot.com/-v38tLvDAxHg/V1k7beVd5SI/AAAAAAAAX7A/1X72bmQ3ia42ww6kJ_61R-CZ6yrYEBSpgCLcB/s400/mate114-ubuntu1604.png" alt=""></p><p><strong>現在 PPA 提供 Mate 1.14.1 包含如下改變（Ubuntu Mate 16.04 默認安裝的是 Mate 1.12.x）：</strong></p><ul><li>客户端的裝飾應用現在可以正確的在所有主題中渲染；</li><li>觸摸板配置現在支持邊緣操作和雙指滾動；</li><li>在 Caja 中的 Python 擴展可以被單獨管理；</li><li>所有三個窗口焦點模式都是可選的；</li><li>Mate Panel 中的所有菜單欄圖標和菜單圖標可以改變大小；</li><li>音量和亮度 OSD 目前可以啓用和禁用；</li><li>更多的改進和 bug 修改；</li></ul><p>Mate 1.14 同時改進了整個桌面環境中對 GTK+ 3 的支持，包括各種 GTK+3 小應用。但是，Ubuntu MATE 的Blog中提到：PPA 的發行包使用 GTK+ 2 編譯是“為了確保對 Ubuntu MATE 16.04 還有各種各樣的第三方 MATE 應用、插件、擴展的支持&quot;。</p>',4)),s("p",null,[t[4]||(t[4]=e("MATE 1.14 的完整修改列表",-1)),n(a,{href:"http://mate-desktop.com/blog/2016-04-08-mate-1-14-released/"},{default:l(()=>[...t[3]||(t[3]=[e("點擊此處",-1)])]),_:1}),t[5]||(t[5]=e("閲讀。",-1))]),t[23]||(t[23]=u(`<h3 id="在-ubuntu-mate-16-04-中升級-mate-1-14-x" tabindex="-1">在 Ubuntu MATE 16.04 中升級 MATE 1.14.x <a class="header-anchor" href="#在-ubuntu-mate-16-04-中升級-mate-1-14-x" aria-label="Permalink to “在 Ubuntu MATE 16.04 中升級 MATE 1.14.x”">​</a></h3><p>在 Ubuntu MATE 16.04 中打開終端，並且輸入如下命令，來從官方的 Xenial MATE PPA 中升級最新的 MATE 桌面環境:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:ubuntu-mate-dev/xenial-mate</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt dist-upgrade</span></span></code></pre></div><p><strong>注意</strong>: mate-netspeed 應用將會在升級中刪除。因為該應用現在已經是 mate-applets 應用報的一部分，所以它依舊是可以使用的。</p><p>一旦升級完成，請重啓你的系統，享受全新的 MATE!</p><h3 id="如何回滾這次升級" tabindex="-1">如何回滾這次升級 <a class="header-anchor" href="#如何回滾這次升級" aria-label="Permalink to “如何回滾這次升級”">​</a></h3><p>如果你並不滿意 MATE 1.14, 比如你遭遇了一些 bug 。或者你想回到 MATE 的官方源版本，你可以使用如下的命令清除 PPA，並且下載降級包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ppa-purge</span></span>
<span class="line"><span>sudo ppa-purge ppa:ubuntu-mate-dev/xenial-mate</span></span></code></pre></div><p>在所有的 MATE 包降級之後，重啓系統。</p>`,9)),s("p",null,[t[7]||(t[7]=e("via ",-1)),n(a,{href:"https://ubuntu-mate.org/blog/mate-desktop-114-for-xenial-xerus/"},{default:l(()=>[...t[6]||(t[6]=[e("Ubuntu MATE blog",-1)])]),_:1})]),t[24]||(t[24]=s("hr",null,null,-1)),s("p",null,[t[9]||(t[9]=e("via: ",-1)),n(a,{href:"http://www.webupd8.org/2016/06/install-mate-114-in-ubuntu-mate-1604.html"},{default:l(()=>[...t[8]||(t[8]=[e("http://www.webupd8.org/2016/06/install-mate-114-in-ubuntu-mate-1604.html",-1)])]),_:1})]),s("p",null,[t[13]||(t[13]=e("作者：",-1)),n(a,{href:"http://www.webupd8.org/p/about.html"},{default:l(()=>[...t[10]||(t[10]=[e("Andrew",-1)])]),_:1}),t[14]||(t[14]=e(" 譯者：",-1)),n(a,{href:"https://github.com/MikeCoder"},{default:l(()=>[...t[11]||(t[11]=[e("MikeCoder",-1)])]),_:1}),t[15]||(t[15]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[18]||(t[18]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:l(()=>[...t[17]||(t[17]=[e("Linux中國",-1)])]),_:1}),t[20]||(t[20]=e(" 榮譽推出",-1))])])}const x=i(d,[["render",A]]);export{k as __pageData,x as default};
